"""extract_docs must not turn auto-generated doc regions into durable facts.

Bug: bootstrap.extract_docs chunks markdown by heading and writes each chunk
to memory as a fact. README's MCP tool table lives between
`<!-- tool-table:start auto-generated -->` and `<!-- tool-table:end -->` and is
regenerated by scripts/gen_tool_table.py. Capturing it produced a fact
asserting "The server registers 14 tools" that stayed active and searchable
long after the live count moved to 18.

Generated regions are, by definition, not authored prose: a fact that mirrors
one is a snapshot that the next regeneration falsifies. They are replaced with
a short pointer instead.

Run with: python -m pytest test_bootstrap_generated.py -v
"""
from pathlib import Path

from bootstrap import extract_docs

README = """# Sample Project

Intro prose that should still be captured verbatim.

## 3. Exposed MCP Tools

<!-- tool-table:start auto-generated -->
The server registers 14 tools.

| Tool | Parameters |
|---|---|
| `memory_write` | `category` |
<!-- tool-table:end -->

Closing prose about the tools.
"""

PLAIN = """# Plain Doc

## Architecture

We chose RRF fusion because it needs no score calibration.
"""


def _write(tmp_path, name, text):
    p = tmp_path / name
    p.write_text(text, encoding="utf-8")
    return p


def test_generated_tool_table_is_not_captured(tmp_path):
    _write(tmp_path, "README.md", README)
    facts = extract_docs(tmp_path)
    blob = " ".join(f["content"] for f in facts)

    assert "The server registers 14 tools" not in blob, (
        "auto-generated tool table was captured as a durable fact")
    assert "| `memory_write` | `category` |" not in blob, (
        "generated table rows leaked into memory")


def test_generated_region_leaves_a_pointer_not_a_snapshot(tmp_path):
    """The chunk should stay useful without carrying a rot-prone number."""
    _write(tmp_path, "README.md", README)
    facts = extract_docs(tmp_path)
    blob = " ".join(f["content"] for f in facts)

    assert "auto-generated" in blob, (
        "expected a pointer noting the region is generated")
    assert "14" not in blob, "the stale tool count survived somewhere in the fact"


def test_surrounding_prose_is_still_captured(tmp_path):
    """Guard against over-filtering: only the generated block is dropped."""
    _write(tmp_path, "README.md", README)
    facts = extract_docs(tmp_path)
    blob = " ".join(f["content"] for f in facts)

    assert "Intro prose that should still be captured" in blob
    assert "Closing prose about the tools" in blob
    assert any("Exposed MCP Tools" in f["content"] for f in facts)


def test_docs_without_generated_regions_are_unchanged(tmp_path):
    _write(tmp_path, "README.md", PLAIN)
    facts = extract_docs(tmp_path)
    blob = " ".join(f["content"] for f in facts)

    assert "We chose RRF fusion because it needs no score calibration" in blob
    assert "auto-generated" not in blob


def test_unbalanced_marker_does_not_eat_the_rest_of_the_doc(tmp_path):
    """A start marker with no end must not swallow the remainder of the file."""
    broken = (
        "# Sample\n\n## Section\n\nbefore\n\n"
        "<!-- tool-table:start auto-generated -->\n\nafter, with no end marker\n"
    )
    _write(tmp_path, "README.md", broken)
    facts = extract_docs(tmp_path)
    blob = " ".join(f["content"] for f in facts)

    assert "before" in blob
    assert "after, with no end marker" in blob, (
        "unbalanced start marker truncated the document")
